package demo; import java.util.*; import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*;
public class Probe { static String esc(String s){return s.replace("\\","\\\\").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t").replace("\f","\\f");} static String parse(Path p, int kind)throws Exception{Properties x=new Properties(); if(kind==0)x.load(Files.newInputStream(p)); else if(kind==1)x.load(Files.newBufferedReader(p,StandardCharsets.UTF_8)); else if(kind==2)x.load(new BufferedReader(new FileReader(p.toFile()))); else x.load(new BufferedReader(new InputStreamReader(Files.newInputStream(p),StandardCharsets.UTF_8))); StringBuilder z=new StringBuilder();for(String k:new TreeSet<>(x.stringPropertyNames()))z.append(esc(k)).append('=').append(esc(x.getProperty(k))).append(';');return z.toString();} public static String rows()throws Exception{File d=new File("properties-load"); d.mkdirs();String[] xs={"a\\ b=c\n","a=one\\\n#two\n","a\\fb\n","a\u00a0b=c\n","a=b\r","a=\\u12G4\n","\\u12G4=x\n","e=é\n"};StringBuilder b=new StringBuilder();for(int i=0;i<xs.length;i++){Path p=new File(d,"p"+i).toPath();Files.writeString(p,xs[i],StandardCharsets.UTF_8);for(int k=0;k<4;k++)try{b.append("x").append(i).append(k).append('=').append(parse(p,k)).append('\n');}catch(Exception e){b.append("x").append(i).append(k).append('=').append(e.getClass().getName()).append(':').append(e.getMessage()).append('\n');}}Path e=new File(d,"empty").toPath();e.toFile().createNewFile();Properties q=new Properties();q.load(Files.newInputStream(e));b.append("empty=").append(q.getProperty("x")).append('\n');Properties dflt=new Properties(); dflt.setProperty("d1","x"); dflt.setProperty("shared","fromDefault");
Properties own=new Properties(dflt); own.setProperty("alpha","1"); own.setProperty("shared","own"); own.setProperty("zeta","2");
java.util.Set<String> names=own.stringPropertyNames();
b.append("names=").append(String.join(",", names)).append('\n');
try{names.add("nope");b.append("add=ok\n");}catch(Throwable t){b.append("add=").append(t.getClass().getName()).append('\n');}
own.setProperty("late","3");
b.append("snapshot=").append(names.contains("late")).append('|').append(names.size()).append('\n');
return b.toString();}public static void main(String[]x)throws Exception{System.out.print(rows());}}